// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.facadeimport timber.log.Timberimport com.roshan.persona.brain.intent.Intentimport com.roshan.persona.brain.skill.SkillContextimport com.roshan.persona.brain.skill.SkillOutputimport com.roshan.persona.common.Result/** * NOUS — Productivity E2E Flow (Module 14 v1.2 — Step 14.5). * * End-to-end smoke test that exercises the full pipeline: * *   User utterance → Intent → Skill → Facade → Engine → Real Android API → Result * * ## Why a dedicated E2E class? * * The strategy v1.2 §"Step 14.5" requires an E2E smoke test. This class: *   1. Provides a [simulate] method that takes a user utterance + simulated *      intent + skill + facade, and returns the full E2E result. *   2. Tracks the execution steps for diagnostics ([E2eTrace]). *   3. Used by [AgentStep14_5Test] to verify the pipeline doesn't break *      end-to-end. * * ## What the E2E flow verifies * *   - Intent slots flow through to the skill (e.g., time="7:00" → AlarmSkill). *   - Skill calls the right facade method (e.g., AlarmSkill → facade.setAlarm). *   - Facade calls the right engine (e.g., facade.setAlarm → AlarmEngine.setAlarm). *   - Engine returns a result (Success / Failure / NeedsPermission). *   - Result converts to ProductivityResult via toProductivityResult(). *   - ProductivityResult converts to SkillOutput via toSkillOutput(). *   - SkillOutput converts to Result<SkillOutput> via Result.Success wrapper. * * If any step fails, the E2E trace shows exactly where. * * @see <a href="docs/strategy/module-14-productivity-strategy-v1.2-final.md">§Step 14.5</a> */class ProductivityE2EFlow(    private val facade: ProductivityFacade,) {    companion object {        private const val TAG = "ProductivityE2E"    }    /**     * Simulate the full E2E flow for a single user utterance.     *     * @param userUtterance  the user's spoken/typed input (for logging only).     * @param intent         the classified intent (with slots filled).     * @param skillId        the ID of the skill to execute.     * @param context        the skill context.     * @return [E2eResult] with the final result + trace.     */    suspend fun simulate(        userUtterance: String,        intent: Intent,        skillId: String,        context: SkillContext,    ): E2eResult {        val trace = mutableListOf<E2eStep>()        trace.add(E2eStep("utterance", "User said: '$userUtterance'"))        trace.add(E2eStep("intent", "Classified as: ${intent::class.simpleName}"))        // Find the skill by ID.        val skill = findSkill(skillId)        if (skill == null) {            trace.add(E2eStep("skill_lookup", "FAILED: Skill '$skillId' not found"))            return E2eResult(null, trace, E2eStatus.SKILL_NOT_FOUND)        }        trace.add(E2eStep("skill_lookup", "Found skill: ${skill.displayName}"))        // Check if intent is supported by this skill.        if (intent::class !in skill.supportedIntents) {            trace.add(E2eStep(                "intent_check",                "FAILED: Skill '${skill.id}' doesn't support ${intent::class.simpleName}",            ))            return E2eResult(null, trace, E2eStatus.INTENT_NOT_SUPPORTED)        }        trace.add(E2eStep("intent_check", "Intent supported by skill"))        // Execute the skill.        trace.add(E2eStep("skill_execute", "Executing skill '${skill.id}'..."))        val result: Result<SkillOutput> = try {            skill.execute(intent, context)        } catch (e: Exception) {            trace.add(E2eStep("skill_execute", "FAILED: ${e::class.simpleName}: ${e.message}"))            return E2eResult(null, trace, E2eStatus.SKILL_CRASHED)        }        // Inspect the result.        return when (result) {            is Result.Success -> {                trace.add(E2eStep("skill_execute", "Skill returned Success"))                when (val output = result.data) {                    is SkillOutput.Success -> {                        trace.add(E2eStep("skill_output", "SkillOutput.Success: ${output.message}"))                        E2eResult(output, trace, E2eStatus.SUCCESS)                    }                    is SkillOutput.NeedsInput -> {                        trace.add(E2eStep("skill_output", "SkillOutput.NeedsInput: ${output.prompt}"))                        E2eResult(output, trace, E2eStatus.NEEDS_INPUT)                    }                    is SkillOutput.NeedsPermission -> {                        trace.add(E2eStep(                            "skill_output",                            "SkillOutput.NeedsPermission: ${output.missingPermissions}",                        ))                        E2eResult(output, trace, E2eStatus.NEEDS_PERMISSION)                    }                    is SkillOutput.Failure -> {                        trace.add(E2eStep("skill_output", "SkillOutput.Failure: ${output.userMessage}"))                        E2eResult(output, trace, E2eStatus.SKILL_FAILED)                    }                    is SkillOutput.Partial -> {                        trace.add(E2eStep("skill_output", "SkillOutput.Partial: ${output.message}"))                        E2eResult(output, trace, E2eStatus.SUCCESS)                    }                }            }            is Result.Failure -> {                trace.add(E2eStep("skill_execute", "Result.Failure: ${result.error}"))                E2eResult(null, trace, E2eStatus.SKILL_FAILED)            }            is Result.Partial<*> -> {                trace.add(E2eStep("skill_execute", "Result.Partial"))                E2eResult(null, trace, E2eStatus.SUCCESS)            }        }    }    /**     * Find a skill by ID (calls into the productivity skills directly).     *     * In production, Brain's SkillRegistry handles this. For the E2E flow,     * we instantiate skills directly to verify their wiring without needing     * a full Hilt graph.     */    private fun findSkill(skillId: String): com.roshan.persona.brain.skill.BrainSkill? {        return when (skillId) {            "set_alarm" -> AlarmSkill(facade)            "set_timer" -> TimerSkill(facade)            "set_reminder" -> ReminderSkill(facade)            "create_note" -> NoteSkill(facade)            "create_calendar_event" -> CalendarSkill(facade)            else -> null        }    }    /**     * Dump the trace to logcat (for debugging E2E test failures).     */    fun dumpTrace(result: E2eResult) {        Timber.tag(TAG).i("════════════════════════════════════════════════════════════════")        Timber.tag(TAG).i("E2E Flow Result: ${result.status}")        Timber.tag(TAG).i("Steps:")        for (step in result.trace) {            Timber.tag(TAG).i("  [${step.name}] ${step.detail}")        }        Timber.tag(TAG).i("════════════════════════════════════════════════════════════════")    }}// ═══════════════════════════════════════════════════════════════════════════// E2E Trace + Result types// ═══════════════════════════════════════════════════════════════════════════/** A single step in the E2E trace. */data class E2eStep(    val name: String,    val detail: String,)/** Final status of an E2E flow. */enum class E2eStatus {    /** Skill executed successfully and returned SkillOutput.Success. */    SUCCESS,    /** Skill returned NeedsInput (missing slot — user must provide input). */    NEEDS_INPUT,    /** Skill returned NeedsPermission (missing Android permission). */    NEEDS_PERMISSION,    /** Skill returned Failure. */    SKILL_FAILED,    /** Skill threw an exception during execute(). */    SKILL_CRASHED,    /** Requested skill ID not found in the registry. */    SKILL_NOT_FOUND,    /** Intent type not supported by the requested skill. */    INTENT_NOT_SUPPORTED,}/** Result of an E2E flow simulation. */data class E2eResult(    val output: SkillOutput?,    val trace: List<E2eStep>,    val status: E2eStatus,) {    /** True if the flow completed successfully. */    val isSuccess: Boolean get() = status == E2eStatus.SUCCESS    /** True if the flow needs user input. */    val needsInput: Boolean get() = status == E2eStatus.NEEDS_INPUT    /** True if the flow needs a permission grant. */    val needsPermission: Boolean get() = status == E2eStatus.NEEDS_PERMISSION    /** True if the flow failed (skill failure or crash). */    val isFailure: Boolean get() = status in setOf(        E2eStatus.SKILL_FAILED,        E2eStatus.SKILL_CRASHED,        E2eStatus.SKILL_NOT_FOUND,        E2eStatus.INTENT_NOT_SUPPORTED,    )}